package com.vishal.ticketbooking.entity;

import jakarta.persistence.*;

// This class becomes the "seats" table in PostgreSQL.
@Entity
// uniqueConstraints: the same seat number (e.g. "A1") can't appear twice
// for the same event. This is a database-level safety net against duplicates.
@Table(name = "seats",
        uniqueConstraints = @UniqueConstraint(columnNames = {"event_id", "seat_number"}))
public class Seat {

    // Primary key, auto-generated by PostgreSQL.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Many seats belong to ONE event (this creates the event_id foreign key).
    // LAZY = the Event is loaded from the DB only when we actually use it (faster).
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "event_id", nullable = false)
    private Event event;

    // Seat label like "A1", "A2".
    @Column(name = "seat_number", nullable = false)
    private String seatNumber;

    // EnumType.STRING stores the text "AVAILABLE" in the DB instead of a number (0, 1, 2).
    // Text stays correct even if we reorder the enum values later.
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private SeatStatus status;

    // Hibernate automatically increases this number every time the row is updated.
    // Used for audit/tracking of changes to the seat (from your resume schema).
    @Version
    private Long version;

    // Required by Hibernate to build objects from DB rows.
    public Seat() {
    }

    // Convenience constructor. New seats always start as AVAILABLE.
    public Seat(Event event, String seatNumber) {
        this.event = event;
        this.seatNumber = seatNumber;
        this.status = SeatStatus.AVAILABLE;
    }

    // Getters and setters (let other classes read/change the private fields).
    public Long getId() { return id; }

    public Event getEvent() { return event; }
    public void setEvent(Event event) { this.event = event; }

    public String getSeatNumber() { return seatNumber; }
    public void setSeatNumber(String seatNumber) { this.seatNumber = seatNumber; }

    public SeatStatus getStatus() { return status; }
    public void setStatus(SeatStatus status) { this.status = status; }

    public Long getVersion() { return version; }
}